-- STORYVERSE X · migration 5 · ingestion bookkeeping and data-quality views
--
-- Operational tables. Nothing here is reachable by anonymous or signed-in
-- visitors: RLS is on with no policies, and privileges are revoked.

create table public.ingestion_runs (
  id               uuid primary key default gen_random_uuid(),
  provider         text not null,
  job              text not null,
  params           jsonb not null default '{}'::jsonb,
  status           text not null default 'running'
                   check (status in ('running','succeeded','partial','failed')),
  started_at       timestamptz not null default now(),
  finished_at      timestamptz,
  items_seen       integer not null default 0,
  items_inserted   integer not null default 0,
  items_updated    integer not null default 0,
  items_unchanged  integer not null default 0,
  items_failed     integer not null default 0,
  -- where to resume if the run stopped early, e.g. {"page": 7}
  cursor           jsonb,
  error            text
);
create index ingestion_runs_lookup on public.ingestion_runs (provider, job, started_at desc);

create table public.ingestion_errors (
  id           bigint generated always as identity primary key,
  run_id       uuid not null references public.ingestion_runs (id) on delete cascade,
  external_id  text,
  message      text not null,
  created_at   timestamptz not null default now()
);
create index ingestion_errors_run on public.ingestion_errors (run_id);

alter table public.ingestion_runs   enable row level security;
alter table public.ingestion_errors enable row level security;
revoke all on public.ingestion_runs, public.ingestion_errors from anon, authenticated;

-- Pairs of visible titles that look like the same work. Candidates only:
-- nothing is merged automatically, an editor decides.
create view public.duplicate_title_candidates
with (security_invoker = true) as
select a.id as title_a, b.id as title_b, a.media_type, a.title, a.release_year
from public.titles a
join public.titles b
  on a.media_type = b.media_type
 and lower(a.title) = lower(b.title)
 and a.release_year is not distinct from b.release_year
 and a.id < b.id
where not a.is_stub and not b.is_stub;

revoke all on public.duplicate_title_candidates from anon, authenticated;


-- ============================================================
-- SOURCE: 20261103000600_site_functions.sql
-- ============================================================

-- STORYVERSE X · migration 6 · site-level functions
--
-- Home page counts, the data-source credits page, and account deletion.

-- ---------------------------------------------------------------------------
-- catalog_stats: how many real titles there are, per medium. Stubs are
-- placeholders for works not ingested yet, so they are not counted.
-- ---------------------------------------------------------------------------
create or replace function public.catalog_stats()
returns jsonb
language sql
stable
set search_path = public
as $$
  select jsonb_build_object(
    'total',   coalesce(sum(c.n), 0),
    'by_type', coalesce(jsonb_object_agg(c.media_type, c.n), '{}'::jsonb)
  )
  from (
    select t.media_type, count(*) as n
    from public.titles t
    where not t.is_stub
    group by t.media_type
  ) c;
$$;

-- ---------------------------------------------------------------------------
-- catalog_attributions: which providers the catalog's data came from, how many
-- titles each supplied, and the credit text each one requires. Only providers
-- that actually supplied a visible title are listed.
-- ---------------------------------------------------------------------------
create or replace function public.catalog_attributions()
returns jsonb
language sql
stable
set search_path = public
as $$
  select coalesce(jsonb_agg(
           jsonb_build_object(
             'provider',        a.provider,
             'titles',          a.titles,
             'attribution',     a.attribution,
             'last_fetched_at', a.last_fetched_at)
           order by a.provider), '[]'::jsonb)
  from (
    select s.provider,
           count(distinct s.title_id) as titles,
           max(s.attribution)         as attribution,
           max(s.fetched_at)          as last_fetched_at
    from public.title_sources s
    join public.titles t on t.id = s.title_id and not t.is_stub
    group by s.provider
  ) a;
$$;

-- ---------------------------------------------------------------------------
-- delete_my_account: permanently removes the caller's account and everything
-- attached to it (profile, library, ratings, notes). SECURITY DEFINER because
-- ordinary users cannot touch auth.users; the function only ever acts on
-- auth.uid(), and takes no argument that could name another user.
-- ---------------------------------------------------------------------------
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  -- profiles and library_entries cascade from auth.users.
  delete from auth.users where id = v_uid;
end;
$$;

revoke all on function
  public.catalog_stats(),
  public.catalog_attributions(),
  public.delete_my_account()
from public, anon, authenticated;

grant execute on function public.catalog_stats(), public.catalog_attributions() to anon, authenticated;
grant execute on function public.delete_my_account() to authenticated;


-- ============================================================
-- SOURCE: 20261104000100_private_notes_and_hardening.sql
-- ============================================================

-- STORYVERSE X · migration 7 · private notes, and small fixes found in review
--
-- 1. Notes leave library_entries.
--
--    library_entries is readable by anyone for the entries of a public profile that
--    are not marked private: that is how a public profile works. Row-level security
--    decides which ROWS a reader gets, and cannot hide one column of a row it lets
--    through. The SQL functions already left notes out for everybody but the owner,
--    but the table itself would have handed them to anyone who queried it directly
--    (for example with the project's anon key). Notes now live in their own table,
--    which only the owner can read or write, so the rule holds at the table too.
--
-- 2. Signing up can no longer fail because two people picked the same username at
--    the same moment.
-- 3. Nothing in the app sets avatar_url, so signed-in users lose the right to write it.
-- 4. A library listing now has a total order, so paging cannot repeat or skip entries
--    that share a timestamp.

-- ---------------------------------------------------------------------------
-- 1. library_notes
-- ---------------------------------------------------------------------------
create table public.library_notes (
  user_id     uuid not null,
  title_id    uuid not null,
  notes       text not null check (char_length(notes) between 1 and 2000),
  updated_at  timestamptz not null default now(),
  primary key (user_id, title_id),
  foreign key (user_id, title_id)
    references public.library_entries (user_id, title_id) on delete cascade
);

create trigger library_notes_set_updated_at
  before update on public.library_notes
  for each row execute function public.set_updated_at();

alter table public.library_notes enable row level security;

create policy "owner reads own notes"
  on public.library_notes for select to authenticated
  using (user_id = (select auth.uid()));

create policy "owner adds own notes"
  on public.library_notes for insert to authenticated
  with check (user_id = (select auth.uid()));

create policy "owner edits own notes"
  on public.library_notes for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy "owner deletes own notes"
  on public.library_notes for delete to authenticated
  using (user_id = (select auth.uid()));

-- Visitors who are not signed in get no access to this table at all.
revoke all on public.library_notes from anon, authenticated;
grant select, insert, update, delete on public.library_notes to authenticated;

-- Carry over any notes that already exist, then drop the old column (and with it
-- its length check).
insert into public.library_notes (user_id, title_id, notes)
select user_id, title_id, btrim(notes, E' \t\r\n')
  from public.library_entries
 where notes is not null and btrim(notes, E' \t\r\n') <> '';

alter table public.library_entries drop column notes;

-- ---------------------------------------------------------------------------
-- Functions that used to read or write library_entries.notes
--
-- get_library_entry and list_library can be called by visitors who are not signed
-- in, and those visitors have no privileges on library_notes. Postgres checks table
-- privileges when a statement runs, and PL/pgSQL only runs the branch it takes, so
-- the statements that touch library_notes sit in branches that only the signed-in
-- owner reaches.
-- ---------------------------------------------------------------------------
create or replace function public.get_library_entry(p_title_id uuid)
returns jsonb
language plpgsql
stable
set search_path = public
as $$
declare
  v_uid   uuid := auth.uid();
  v_entry jsonb;
begin
  if v_uid is null then
    return null;
  end if;

  select (to_jsonb(e) - 'user_id') || jsonb_build_object('notes', n.notes)
    into v_entry
    from public.library_entries e
    left join public.library_notes n on n.user_id = e.user_id and n.title_id = e.title_id
   where e.user_id = v_uid and e.title_id = p_title_id;

  return v_entry;
end;
$$;

-- Create or update the caller's entry. Null arguments mean "leave as is";
-- notes given as empty text (or only whitespace) are removed.
create or replace function public.upsert_library_entry(
  p_title_id      uuid,
  p_status        text     default null,
  p_progress      integer  default null,
  p_rating        integer  default null,
  p_clear_rating  boolean  default false,
  p_notes         text     default null,
  p_is_private    boolean  default null
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  v_uid       uuid := auth.uid();
  v_title     public.titles;
  v_old       public.library_entries;
  v_total     integer;
  v_status    text;
  v_progress  integer;
  v_rating    smallint;
  v_row       public.library_entries;
  v_notes     text;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  select * into v_title from public.titles where id = p_title_id and not is_stub;
  if not found then
    raise exception 'title_not_found' using errcode = 'P0002';
  end if;

  select * into v_old from public.library_entries where user_id = v_uid and title_id = p_title_id;

  v_total    := public.title_progress_total(v_title);
  v_status   := coalesce(p_status, v_old.status, 'planned');
  v_progress := coalesce(p_progress, v_old.progress, 0);

  if v_status not in ('planned','in_progress','completed','paused','dropped','repeating') then
    raise exception 'invalid_status' using errcode = '22023';
  end if;
  if v_progress < 0 then
    raise exception 'invalid_progress' using errcode = '22023';
  end if;
  if v_total is not null and v_progress > v_total then
    raise exception 'progress_exceeds_total' using errcode = '22003';
  end if;

  if v_status = 'completed' and v_total is not null then
    v_progress := v_total;
  end if;
  if v_status = 'in_progress' and v_total is not null and v_total > 0 and v_progress >= v_total then
    v_status := 'completed';
  end if;

  if p_clear_rating then
    v_rating := null;
  elsif p_rating is not null then
    if p_rating not between 1 and 10 then
      raise exception 'invalid_rating' using errcode = '22023';
    end if;
    v_rating := p_rating;
  else
    v_rating := v_old.rating;
  end if;

  insert into public.library_entries as e
    (user_id, title_id, status, progress, rating, is_private, started_at, completed_at)
  values (
    v_uid, p_title_id, v_status, v_progress, v_rating,
    coalesce(p_is_private, false),
    case when v_status <> 'planned' or v_progress > 0 then current_date end,
    case when v_status = 'completed' then current_date end
  )
  on conflict (user_id, title_id) do update set
    status       = excluded.status,
    progress     = excluded.progress,
    rating       = excluded.rating,
    is_private   = coalesce(p_is_private, e.is_private),
    started_at   = coalesce(e.started_at, excluded.started_at),
    completed_at = case when excluded.status = 'completed'
                        then coalesce(e.completed_at, current_date)
                        else e.completed_at end
  returning * into v_row;

  if p_notes is not null then
    v_notes := nullif(btrim(p_notes, E' \t\r\n'), '');
    if v_notes is null then
      delete from public.library_notes where user_id = v_uid and title_id = p_title_id;
    else
      insert into public.library_notes (user_id, title_id, notes)
      values (v_uid, p_title_id, v_notes)
      on conflict (user_id, title_id) do update set notes = excluded.notes;
    end if;
  end if;

  select n.notes into v_notes
    from public.library_notes n
   where n.user_id = v_uid and n.title_id = p_title_id;

  return (to_jsonb(v_row) - 'user_id') || jsonb_build_object('notes', v_notes);
end;
$$;

-- A user's library. With no user id it returns the caller's own. RLS decides which
-- entries a viewer may see; notes are only ever returned to the owner.
create or replace function public.list_library(
  p_user_id  uuid     default null,
  p_status   text     default null,
  p_limit    integer  default 200,
  p_offset   integer  default 0
)
returns jsonb
language plpgsql
stable
set search_path = public
as $$
declare
  v_user    uuid := coalesce(p_user_id, auth.uid());
  v_limit   integer := least(greatest(coalesce(p_limit, 200), 1), 500);
  v_offset  integer := greatest(coalesce(p_offset, 0), 0);
  v_total   bigint;
  v_counts  jsonb;
  v_items   jsonb;
begin
  if v_user is null then
    return jsonb_build_object('total', 0, 'counts', '{}'::jsonb, 'items', '[]'::jsonb);
  end if;

  select coalesce(jsonb_object_agg(s.status, s.n), '{}'::jsonb)
    into v_counts
    from (select status, count(*) as n
            from public.library_entries
           where user_id = v_user
           group by status) s;

  select count(*) into v_total
    from public.library_entries e
   where e.user_id = v_user and (p_status is null or e.status = p_status);

  -- (v_user = auth.uid()) is null for a visitor who is not signed in, which takes the else branch.
  if v_user = auth.uid() then
    select coalesce(jsonb_agg(
             jsonb_build_object(
               'entry', (to_jsonb(p) - 'user_id') || jsonb_build_object('notes', n.notes),
               'title', public.title_card(t),
               'progress_unit', public.progress_unit(t.media_type),
               'progress_total', public.title_progress_total(t))
             order by p.updated_at desc, p.title_id), '[]'::jsonb)
      into v_items
      from (
        select e.*
          from public.library_entries e
         where e.user_id = v_user and (p_status is null or e.status = p_status)
         order by e.updated_at desc, e.title_id
         limit v_limit offset v_offset
      ) p
      join public.titles t on t.id = p.title_id
      left join public.library_notes n on n.user_id = p.user_id and n.title_id = p.title_id;
  else
    select coalesce(jsonb_agg(
             jsonb_build_object(
               'entry', to_jsonb(p) - 'user_id',
               'title', public.title_card(t),
               'progress_unit', public.progress_unit(t.media_type),
               'progress_total', public.title_progress_total(t))
             order by p.updated_at desc, p.title_id), '[]'::jsonb)
      into v_items
      from (
        select e.*
          from public.library_entries e
         where e.user_id = v_user and (p_status is null or e.status = p_status)
         order by e.updated_at desc, e.title_id
         limit v_limit offset v_offset
      ) p
      join public.titles t on t.id = p.title_id;
  end if;

  return jsonb_build_object('total', v_total, 'counts', v_counts, 'items', v_items);
end;
$$;

-- Everything the app stores about the caller, as one JSON document.
create or replace function public.export_my_data()
returns jsonb
language plpgsql
stable
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  return jsonb_build_object(
    'exported_at', now(),
    'profile', public.get_profile(null),
    'library', coalesce((
      select jsonb_agg(
               (to_jsonb(e) - 'user_id')
               || jsonb_build_object('notes', n.notes, 'title', t.title, 'media_type', t.media_type, 'title_slug', t.slug)
               order by e.updated_at desc, e.title_id)
      from public.library_entries e
      join public.titles t on t.id = e.title_id
      left join public.library_notes n on n.user_id = e.user_id and n.title_id = e.title_id
      where e.user_id = auth.uid()
    ), '[]'::jsonb)
  );
end;
$$;

-- create or replace keeps the privileges the earlier migration granted. Said again
-- here so that this file can be read on its own.
revoke all on function
  public.get_library_entry(uuid),
  public.upsert_library_entry(uuid, text, integer, integer, boolean, text, boolean),
  public.list_library(uuid, text, integer, integer),
  public.export_my_data()
from public, anon, authenticated;

grant execute on function
  public.get_library_entry(uuid),
  public.list_library(uuid, text, integer, integer)
to anon, authenticated;

grant execute on function
  public.upsert_library_entry(uuid, text, integer, integer, boolean, text, boolean),
  public.export_my_data()
to authenticated;

-- ---------------------------------------------------------------------------
-- 2. handle_new_user: a username taken between the sign-up form's check and this
--    insert no longer aborts the sign-up. The new member gets a generated name
--    and can change it in Settings.
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_wanted    text := new.raw_user_meta_data ->> 'username';
  v_generated text := 'user_' || substr(replace(new.id::text, '-', ''), 1, 12);
  v_username  text;
begin
  if v_wanted is not null
     and v_wanted ~ '^[A-Za-z0-9_]{3,24}$'
     and not exists (select 1 from public.profiles p where lower(p.username) = lower(v_wanted)) then
    v_username := v_wanted;
  else
    v_username := v_generated;
  end if;

  begin
    insert into public.profiles (id, username) values (new.id, v_username);
  exception when unique_violation then
    if v_username = v_generated then
      raise;
    end if;
    insert into public.profiles (id, username) values (new.id, v_generated);
  end;
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. avatar_url is not written by anything yet.
-- ---------------------------------------------------------------------------
revoke update (avatar_url) on public.profiles from authenticated;


-- ============================================================
-- SOURCE: 20261106000100_streaming_watch.sql
-- ============================================================

-- STORYVERSE X · migration 8 · official watch links, licensed episodes and private playback progress
--
-- IMPORTANT:
--   * Watch links are curated HTTPS links to official provider pages.
--   * Built-in playback is exposed only for published episodes with an explicit
--     rights-holder confirmation and an HTTPS HLS/MP4 source.
--   * The public anon key cannot add, edit or remove provider/episode records.
--   * Per-user watch progress is private and protected by RLS.

create table public.watch_catalog_admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);

alter table public.watch_catalog_admins enable row level security;
revoke all on public.watch_catalog_admins from public, anon, authenticated;

create or replace function public.is_watch_catalog_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select auth.uid() is not null and exists (
    select 1
    from public.watch_catalog_admins a
    where a.user_id = auth.uid()
  );
$$;
revoke all on function public.is_watch_catalog_admin() from public, anon;
grant execute on function public.is_watch_catalog_admin() to authenticated;

create table public.title_watch_links (
  id uuid primary key default gen_random_uuid(),
  title_id uuid not null references public.titles (id) on delete cascade,
  provider_name text not null check (char_length(btrim(provider_name)) between 2 and 60),
  url text not null check (url ~ '^https://'),
  country_code text not null default 'IN' check (country_code ~ '^[A-Z]{2}$'),
  availability text not null default 'unknown'
    check (availability in ('subscription', 'free', 'ads', 'rent', 'buy', 'unknown')),
  audio_languages text[] not null default '{}',
  subtitle_languages text[] not null default '{}',
  is_official boolean not null default false,
  is_active boolean not null default true,
  verified_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (title_id, provider_name, country_code)
);
create index title_watch_links_title_active on public.title_watch_links (title_id, country_code) where is_active and is_official;
create trigger title_watch_links_set_updated_at
  before update on public.title_watch_links
  for each row execute function public.set_updated_at();

create table public.title_episodes (
  id uuid primary key default gen_random_uuid(),
  title_id uuid not null references public.titles (id) on delete cascade,
  season_number integer not null default 1 check (season_number between 1 and 999),
  episode_number integer not null check (episode_number between 1 and 99999),
  episode_title text not null check (char_length(btrim(episode_title)) between 1 and 160),
  synopsis text check (char_length(synopsis) <= 3000),
  runtime_seconds integer check (runtime_seconds is null or runtime_seconds between 1 and 86400),
  stream_url text,
  stream_type text check (stream_type is null or stream_type in ('hls', 'mp4')),
  rights_holder text,
  license_reference text,
  license_confirmed boolean not null default false,
  license_confirmed_at timestamptz,
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (title_id, season_number, episode_number),
  check (
    (stream_url is null and stream_type is null)
    or (stream_url ~ '^https://' and stream_type in ('hls', 'mp4'))
  ),
  check (
    not is_published
    or (
      license_confirmed
      and stream_url is not null
      and rights_holder is not null
      and char_length(btrim(rights_holder)) > 0
      and license_confirmed_at is not null
    )
  )
);
create index title_episodes_title_order on public.title_episodes (title_id, season_number, episode_number);
create trigger title_episodes_set_updated_at
  before update on public.title_episodes
  for each row execute function public.set_updated_at();

create table public.watch_progress (
  user_id uuid not null references public.profiles (id) on delete cascade,
  title_id uuid not null references public.titles (id) on delete cascade,
  episode_id uuid not null references public.title_episodes (id) on delete cascade,
  position_seconds integer not null default 0 check (position_seconds >= 0),
  duration_seconds integer not null check (duration_seconds between 1 and 86400),
  completed boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (user_id, episode_id),
  check (position_seconds <= duration_seconds)
);
create index watch_progress_user_updated on public.watch_progress (user_id, updated_at desc);
create trigger watch_progress_set_updated_at
  before update on public.watch_progress
  for each row execute function public.set_updated_at();

alter table public.title_watch_links enable row level security;
alter table public.title_episodes enable row level security;
alter table public.watch_progress enable row level security;

create policy "public reads curated official watch links"
  on public.title_watch_links for select to anon, authenticated
  using (is_active and is_official);
create policy "watch admins manage provider links"
  on public.title_watch_links for all to authenticated
  using (public.is_watch_catalog_admin())
  with check (public.is_watch_catalog_admin());

create policy "public reads published licensed episodes"
  on public.title_episodes for select to anon, authenticated
  using (is_published and license_confirmed);
create policy "watch admins manage licensed episodes"
  on public.title_episodes for all to authenticated
  using (public.is_watch_catalog_admin())
  with check (public.is_watch_catalog_admin());

create policy "members read their own watch progress"
  on public.watch_progress for select to authenticated
  using (user_id = (select auth.uid()));
revoke all on public.title_watch_links, public.title_episodes, public.watch_progress from public, anon, authenticated;
grant select on public.title_watch_links, public.title_episodes to anon, authenticated;
grant select on public.watch_progress to anon, authenticated;

-- One public read returns official platform links, licensed playable episodes,
-- and only the signed-in viewer's own progress (the progress table RLS applies).
create or replace function public.get_watch_catalog(p_title_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_build_object(
    'providers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', w.id,
        'provider_name', w.provider_name,
        'url', w.url,
        'country_code', w.country_code,
        'availability', w.availability,
        'audio_languages', w.audio_languages,
        'subtitle_languages', w.subtitle_languages,
        'verified_at', w.verified_at
      ) order by w.provider_name)
      from public.title_watch_links w
      where w.title_id = t.id and w.is_active and w.is_official
    ), '[]'::jsonb),
    'episodes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', e.id,
        'season_number', e.season_number,
        'episode_number', e.episode_number,
        'episode_title', e.episode_title,
        'synopsis', e.synopsis,
        'runtime_seconds', e.runtime_seconds,
        'stream_url', e.stream_url,
        'stream_type', e.stream_type,
        'position_seconds', coalesce(wp.position_seconds, 0),
        'duration_seconds', wp.duration_seconds,
        'completed', coalesce(wp.completed, false)
      ) order by e.season_number, e.episode_number)
      from public.title_episodes e
      left join public.watch_progress wp
        on wp.episode_id = e.id and wp.user_id = auth.uid()
      where e.title_id = t.id and e.is_published and e.license_confirmed
    ), '[]'::jsonb)
  )
  from public.titles t
  where t.id = p_title_id and not t.is_stub;
$$;

create or replace function public.save_watch_progress(
  p_title_id uuid,
  p_episode_id uuid,
  p_position_seconds integer,
  p_duration_seconds integer,
  p_completed boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_position integer;
  v_row public.watch_progress;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if p_position_seconds is null or p_position_seconds < 0
     or p_duration_seconds is null or p_duration_seconds < 1 or p_duration_seconds > 86400 then
    raise exception 'invalid_watch_position' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.title_episodes e
    where e.id = p_episode_id
      and e.title_id = p_title_id
      and e.is_published
      and e.license_confirmed
  ) then
    raise exception 'episode_not_available' using errcode = 'P0002';
  end if;

  v_position := least(p_position_seconds, p_duration_seconds);
  insert into public.watch_progress as wp
    (user_id, title_id, episode_id, position_seconds, duration_seconds, completed)
  values
    (v_user_id, p_title_id, p_episode_id, v_position, p_duration_seconds,
     coalesce(p_completed, false) or v_position >= greatest(0, p_duration_seconds - 15))
  on conflict (user_id, episode_id) do update set
    title_id = excluded.title_id,
    position_seconds = excluded.position_seconds,
    duration_seconds = excluded.duration_seconds,
    completed = wp.completed or excluded.completed
  returning * into v_row;

  return jsonb_build_object(
    'episode_id', v_row.episode_id,
    'position_seconds', v_row.position_seconds,
    'duration_seconds', v_row.duration_seconds,
    'completed', v_row.completed,
    'updated_at', v_row.updated_at
  );
end;
$$;

-- Admin-only upserts. Public/anon users cannot call these functions.
create or replace function public.upsert_watch_provider(
  p_title_id uuid,
  p_provider_name text,
  p_url text,
  p_country_code text default 'IN',
  p_availability text default 'unknown',
  p_audio_languages text[] default '{}',
  p_subtitle_languages text[] default '{}'
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_country text := upper(coalesce(p_country_code, 'IN'));
  v_availability text := coalesce(p_availability, 'unknown');
begin
  if not public.is_watch_catalog_admin() then
    raise exception 'not_watch_admin' using errcode = '42501';
  end if;
  if p_provider_name is null or char_length(btrim(p_provider_name)) not between 2 and 60
     or p_url is null or p_url !~ '^https://'
     or v_country !~ '^[A-Z]{2}$'
     or v_availability not in ('subscription', 'free', 'ads', 'rent', 'buy', 'unknown') then
    raise exception 'invalid_watch_provider' using errcode = '22023';
  end if;
  if not exists (select 1 from public.titles t where t.id = p_title_id and not t.is_stub) then
    raise exception 'title_not_found' using errcode = 'P0002';
  end if;

  insert into public.title_watch_links as w
    (title_id, provider_name, url, country_code, availability,
     audio_languages, subtitle_languages, is_official, is_active, verified_at)
  values
    (p_title_id, btrim(p_provider_name), p_url, v_country, v_availability,
     coalesce(p_audio_languages, '{}'), coalesce(p_subtitle_languages, '{}'), true, true, now())
  on conflict (title_id, provider_name, country_code) do update set
    url = excluded.url,
    availability = excluded.availability,
    audio_languages = excluded.audio_languages,
    subtitle_languages = excluded.subtitle_languages,
    is_official = true,
    is_active = true,
    verified_at = now()
  returning w.id into v_id;
  return v_id;
end;
$$;

create or replace function public.upsert_watch_episode(
  p_title_id uuid,
  p_season_number integer,
  p_episode_number integer,
  p_episode_title text,
  p_runtime_seconds integer,
  p_stream_url text,
  p_stream_type text,
  p_rights_holder text,
  p_license_reference text default null,
  p_confirmed_rights boolean default false
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.is_watch_catalog_admin() then
    raise exception 'not_watch_admin' using errcode = '42501';
  end if;
  if not coalesce(p_confirmed_rights, false) then
    raise exception 'rights_confirmation_required' using errcode = '22023';
  end if;
  if p_episode_title is null or char_length(btrim(p_episode_title)) not between 1 and 160
     or p_season_number is null or p_season_number not between 1 and 999
     or p_episode_number is null or p_episode_number not between 1 and 99999
     or p_runtime_seconds is not null and p_runtime_seconds not between 1 and 86400
     or p_stream_url is null or p_stream_url !~ '^https://'
     or p_stream_type not in ('hls', 'mp4')
     or p_rights_holder is null or char_length(btrim(p_rights_holder)) = 0 then
    raise exception 'invalid_watch_episode' using errcode = '22023';
  end if;
  if not exists (select 1 from public.titles t where t.id = p_title_id and not t.is_stub) then
    raise exception 'title_not_found' using errcode = 'P0002';
  end if;

  insert into public.title_episodes as e
    (title_id, season_number, episode_number, episode_title, runtime_seconds,
     stream_url, stream_type, rights_holder, license_reference,
     license_confirmed, license_confirmed_at, is_published)
  values
    (p_title_id, p_season_number, p_episode_number, btrim(p_episode_title), p_runtime_seconds,
     p_stream_url, p_stream_type, btrim(p_rights_holder), nullif(btrim(p_license_reference), ''),
     true, now(), true)
  on conflict (title_id, season_number, episode_number) do update set
    episode_title = excluded.episode_title,
    runtime_seconds = excluded.runtime_seconds,
    stream_url = excluded.stream_url,
    stream_type = excluded.stream_type,
    rights_holder = excluded.rights_holder,
    license_reference = excluded.license_reference,
    license_confirmed = true,
    license_confirmed_at = now(),
    is_published = true
  returning e.id into v_id;
  return v_id;
end;
$$;

revoke all on function public.get_watch_catalog(uuid) from public, anon, authenticated;
